#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_tempPressureActuate: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_saturationActuate: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_tempPressureActuate.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_saturationActuate.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_tempPressureActuate(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_tempPressureActuate.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_tempPressureActuate_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn get_saturationActuate(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_saturationActuate.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_saturationActuate_num_invalid() -> u64
{
  return 0;
}
